package com.seniorlink.app
import android.app.*;import android.content.*;import android.os.Build;import androidx.core.app.NotificationCompat
class ReminderReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){val id="seniorlink_reminders";if(Build.VERSION.SDK_INT>=26)c.getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel(id,"Lembretes",NotificationManager.IMPORTANCE_HIGH));if(Build.VERSION.SDK_INT<33||c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")==0)c.getSystemService(NotificationManager::class.java).notify(i.getIntExtra("id",1),NotificationCompat.Builder(c,id).setSmallIcon(R.drawable.ic_seniorlink).setContentTitle(i.getStringExtra("title")).setContentText(i.getStringExtra("desc")).setAutoCancel(true).build())}}